const enabled = false;
const owner = 'YOUR_OWNER';
const repo = 'YOUR_PRIVATE_REPOSITORY';
const scope = 'rss-demo';
const maxUsd = 0.03;
const flow = 'rss';
const slug = 'rss-revision-ledger';
// Only an operator may edit the credential destinations and spending limit.
if (!enabled) throw new Error('Setup required. Connect both credentials, seed the private state file, review the cap and enable the workflow copy.');
if (!/^[A-Za-z0-9-]{1,39}$/.test(owner) || !/^[A-Za-z0-9_-]{1,100}$/.test(repo) ||
    !/^[a-z0-9-]{1,60}$/.test(scope) || !Number.isFinite(maxUsd) || maxUsd <= 0 || maxUsd > 10)
  throw new Error('Invalid private state destination or per-run spending limit.');
const items = $input.all();
if (items.length !== 1) throw new Error('Provide one captured export per execution.');
const { sequence, input, expectedOffers } = items[0].json;
if (!Number.isSafeInteger(sequence) || sequence < 1 || !input || Array.isArray(input) || typeof input !== 'object')
  throw new Error('One immutable positive sequence and one Actor input object are required.');
const allowed = {
  merchant:['offers','feedXml','feedUrl','authorizedFetch','maxResults'],
  supplier:['demoCase','baseline','incoming','priceTolerancePercent'],
  migration:['demoCase','redirectMap','observations','previousObservations'],
  rss:['feedXml','feedUrl','authorizedFetch','previousXml','maxResults']
};
if (Object.keys(input).some(k=>!allowed[flow].includes(k)))
  throw new Error('Unexpected Actor option. This integration never requests a billable demo or optional receipt.');
if (flow === 'merchant' || flow === 'rss') {
  if ('maxResults' in input && (!Number.isSafeInteger(input.maxResults) || input.maxResults < 1 || input.maxResults > 5000))
    throw new Error('The requested output limit must be a whole number from 1 through 5000.');
  const sources = (flow === 'merchant' ? ['offers','feedXml','feedUrl'] : ['feedXml','feedUrl']).filter(k=>k in input);
  if (sources.length !== 1 || ('feedUrl' in input && input.authorizedFetch !== true))
    throw new Error('Supply one authorized current source.');
} else if ('demoCase' in input && Object.keys(input).length !== 1)
  throw new Error('Keep the demo separate from production data.');
else if (!('demoCase' in input) && (flow === 'supplier' ? !input.incoming : !input.redirectMap || !input.observations))
  throw new Error('The source snapshot or observations are missing.');
if (flow === 'merchant' && (!Number.isSafeInteger(expectedOffers) || expectedOffers < 0 || expectedOffers > 5000 ||
    (input.maxResults ?? 5000) < expectedOffers))
  throw new Error('Supply the trusted distinct offer count from the completed export, within the requested output limit.');
if (flow === 'merchant' && maxUsd+Number.EPSILON < (5+90*expectedOffers)/100000)
  throw new Error('Operator cap cannot cover the expected distinct offers and default start. Review the rate and cap before dispatch.');
if (flow === 'supplier' && input.incoming && (!input.incoming.rows || !Array.isArray(input.incoming.rows) ||
    !input.incoming.rows.length || input.incoming.rows.length > 5000 ||
    !Number.isSafeInteger(items[0].json.expectedIncomingRows) || input.incoming.rows.length !== items[0].json.expectedIncomingRows))
  throw new Error('The publisher must confirm a complete incoming export and its original row count.');
if (flow === 'supplier' && input.incoming && maxUsd < 0.85 || flow === 'migration' && input.redirectMap && maxUsd < 2.75)
  throw new Error('Operator cap does not cover one paid full report.');
function canonical(value) {
  if (Array.isArray(value)) return '['+value.map(canonical).join(',')+']';
  if (value!==null && typeof value==='object') return '{'+Object.keys(value).sort().map(k=>JSON.stringify(k)+':'+canonical(value[k])).join(',')+'}';
  return JSON.stringify(value);
}
const crypto = require('crypto');
const signature = crypto.createHash('sha256').update(canonical({sequence,input,maxUsd,expectedOffers:expectedOffers??null})).digest('hex');
return [{json:{flow,slug,owner,repo,scope,maxUsd,sequence,input,expectedOffers:expectedOffers??null,signature}}];

const c=$('Configure connection').first().json,r=$json.body;
if(r?.private !== true || r.full_name?.toLowerCase() !== (c.owner+'/'+c.repo).toLowerCase())
  throw new Error('This customer-owned state repository must be private.');
return [{json:{verified:true}}];

const c=$('Configure connection').first().json,file=$json.body;
if(file?.type!=='file' || file.encoding!=='base64' || !/^[a-f0-9]{40}$/.test(file.sha) || file.size>20000) throw new Error('Invalid private state file.');
const st=JSON.parse(Buffer.from(file.content,'base64').toString('utf8'));
if(st.version!==1 || !Number.isSafeInteger(st.lastSequence) || st.lastSequence<0 ||
   (st.baselineStore!==null && (!/^[a-zA-Z0-9]+$/.test(st.baselineStore) || !/^[a-f0-9]{64}$/.test(st.baselineDigest??''))) ||
   (st.baselineStore===null && st.baselineDigest!=null)) throw new Error('Unexpected journal schema or missing baseline fingerprint.');
let action='start';
if(c.sequence<=st.lastSequence) action='duplicate';
else if(st.pending!==null) {
 if(st.pending?.sequence!==c.sequence || st.pending.signature!==c.signature || !/^[a-zA-Z0-9]+$/.test(st.pending.runId??'')) throw new Error('Unresolved operation. Reconcile the recorded intent; do not start another run.');
 action='resume';
}
return [{json:{state:st,sha:file.sha,action}}];

const c=$('Configure connection').first().json,st=$('Inspect state').first().json.state;
const input={...c.input};
function canonical(x){
 if(Array.isArray(x))return '['+x.map(canonical).join(',')+']';
 if(x!==null && typeof x==='object')return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';
 return JSON.stringify(x);
}
if(st.baselineStore && !('demoCase' in input) && ['supplier','rss'].includes(c.flow)){
 const capture=c.flow==='supplier'?$json.body?.incoming:$json.body;
 if(!capture || require('crypto').createHash('sha256').update(canonical(capture)).digest('hex')!==st.baselineDigest)
    throw new Error('Prior capture changed or expired. Recover the approved baseline before starting a new run.');
}
if(c.flow==='supplier' && !('demoCase' in input)) {
 if(st.baselineStore){
  if('baseline' in input)throw new Error('Stored baseline already exists. Remove the initial baseline.');
  input.baseline=$json.body?.incoming;
 }
 if(!input.baseline?.rows?.length)throw new Error('Provide the first authorized baseline or restore the previous run storage.');
}
if(c.flow==='rss' && st.baselineStore) {
 if('previousXml' in input)throw new Error('Remove previousXml once the checkpoint exists.');
 if($json.body?.version!==1 || !$json.body?.entries)throw new Error('Prior checkpoint is unavailable.');
 input.baseline=$json.body;
}
return [{json:{input}}];

const c=$('Configure connection').first().json;
const {state,sha}=$('Inspect state').first().json;
const pending={sequence:c.sequence,signature:c.signature,execution:String($execution.id),runId:null};
const nextState={...state,pending};

if(!/^[a-f0-9]{40}$/.test(sha??''))throw new Error('Journal revision missing.');
const content=Buffer.from(JSON.stringify(nextState),'utf8').toString('base64');
return [{json:{journalWrite:{message:'Update workflow journal',sha,content}}}];

const sha=$json.body?.content?.sha;
if(!/^[a-f0-9]{40}$/.test(sha??'') || sha===$('Inspect state').first().json.sha) throw new Error('No new journal revision acknowledged. Keep the stream on hold.');
return [{json:{acknowledged:true}}];

const id=$json.body?.data?.id;
if(!/^[A-Za-z0-9]+$/.test(id??'')) throw new Error('No confirmed run ID. Keep this operation locked and reconcile.');
return [{json:{runId:id}}];

const c=$('Configure connection').first().json;
const {state}=$('Inspect state').first().json;
const sha=$('Claim operation').first().json.body.content.sha;
const pending={sequence:c.sequence,signature:c.signature,execution:String($execution.id),runId:$json.runId};
const nextState={...state,pending};

if(!/^[a-f0-9]{40}$/.test(sha??''))throw new Error('Journal revision missing.');
const content=Buffer.from(JSON.stringify(nextState),'utf8').toString('base64');
return [{json:{journalWrite:{message:'Update workflow journal',sha,content}}}];

const r=$json.body?.data;
if(r?.id!==$('Prepare lookup').first().json.runId)throw new Error('Run receipt mismatch.');
if(!['SUCCEEDED','FAILED','ABORTED','TIMED-OUT'].includes(r.status))throw new Error('Run pending. Repeat the same sequence and input to resume without a new start.');
return [{json:{terminal:true}}];

const r=$json.body?.data;
if(!r || r.id!==$('Prepare lookup').first().json.runId || r.actId!=='IkKwNzFXmvdbhkRSg' ||
   ![r.defaultDatasetId,r.defaultKeyValueStoreId].every(x=>typeof x==='string' && /^[A-Za-z0-9]+$/.test(x)))
 throw new Error('Run identity or storage mismatch.');
if(!['SUCCEEDED','FAILED','ABORTED','TIMED-OUT'].includes(r.status))throw new Error('Run pending. Repeat the same sequence and input to resume without a new start.');
return [{json:r}];

const run=$('Check run identity').first().json,outcome=$json.body?.outcome;
if(run.status!=='SUCCEEDED' || outcome!=='complete') {
 const reason=['plan_required','plan_limit','free_limit','budget_limit','budget_insufficient','result_limit','source_error','invalid_input'].includes(outcome)?outcome:run.status;
 throw new Error('No complete delivery ('+reason+'). Reconcile this observation; baseline held.');
}
return [{json:{complete:true}}];

const c = $('Configure connection').first().json;
const state = $('Inspect state').first().json;
const run = $('Check run identity').first().json;
const summary = $('Read run summary').first().json.body;
const rows = $('Read delivered rows').first().json.body;
function check(test,message) { if (!test) throw new Error(message+' State was not advanced. Inspect this run before any new POST.'); }
function same(a,b) { return canonical(a) === canonical(b); }
// Actor reports use sorted JSON with UTF-8 and integer counts, including SKU/path strings.
function canonical(x) {
  if (x === null || typeof x !== 'object') return JSON.stringify(x);
  if (Array.isArray(x)) return '['+x.map(canonical).join(',')+']';
  return '{'+Object.keys(x).sort().map(k=>JSON.stringify(k)+':'+canonical(x[k])).join(',')+'}';
}
const digest = x=>require('crypto').createHash('sha256').update(canonical(x)).digest('hex');
const isDigest=x=>typeof x==='string' && /^[a-f0-9]{64}$/.test(x);
const integer=n=>Number.isSafeInteger(n) && n >= 0;
const record=x=>x && typeof x==='object' && !Array.isArray(x);
check(record(summary) && summary.outcome === 'complete' && Array.isArray(rows),'Incomplete service, plan restriction or invalid dataset.');
const ledger = run.chargedEventCounts;
check(record(ledger) && Object.values(ledger).every(integer),'Missing platform charge counters.');
const event = {merchant:'offer-audited',rss:'feed-change',migration:'migration-audited',supplier:'catalog-reconciled'}[c.flow];
const reportProduct = c.flow==='supplier' || c.flow==='migration';
const preview = reportProduct && 'demoCase' in c.input;
const expectedCharge = reportProduct ? (preview?0:1) : rows.length;
check((ledger['apify-actor-start']??0) <= (reportProduct?0:1),'Unexpected number of platform start events at the default memory.');
for(const [key,count] of Object.entries(ledger)) {
  if (!count || key === event || (!reportProduct && key==='apify-actor-start')) continue;
  throw new Error('Unexpected paid event. Preserve the journal and reconcile.');
}
check((ledger[event]??0) === expectedCharge,'PPE counter and delivered unit count disagree.');
let route, result, advanceBaseline=false, nextCapture=null;
if (!reportProduct) {
  check(integer(summary.matched) && summary.matched===rows.length && summary.returned===rows.length && summary.event===event &&
        rows.every(x=>record(x)&&typeof x.id==='string'&&x.id) && new Set(rows.map(x=>x.id)).size===rows.length,
        'Incomplete or duplicate business units.');
}
if (c.flow==='merchant') {
  check(summary.uniqueOffers===rows.length && summary.uniqueOffers===c.expectedOffers &&
        integer(summary.inputOffers) && summary.inputOffers>=summary.uniqueOffers,'Catalog coverage differs from the export manifest.');
  check(rows.every(x=>['passed_checks','review'].includes(x.status) && Array.isArray(x.findings) &&
        (x.status==='review')===Boolean(x.findings.length)),'Unknown offer finding.');
  const corrections=rows.filter(x=>x.status==='review');
  route=!rows.length?'EMPTY_CATALOG':corrections.length?'HOLD_EXPORT':'READY_FOR_REVIEW';
  const access=c.input.feedUrl || c.expectedOffers>25 ? 'paid_feature' : 'free_compatible_inline';
  result={audited:rows.length,access,corrections};
} else if (c.flow === 'rss') {
  const cp=$('Read detail').first().json.body;
  const entries=cp?.entries;
  check(summary.checkpointReady===true && cp?.version===1 && isDigest(cp.feedKey) && record(entries) &&
        Object.keys(entries).length===summary.entries && summary.unchanged===summary.entries-rows.length &&
        integer(summary.previousOnly),'RSS checkpoint and coverage disagree.');
  check(Object.entries(entries).every(([id,v])=>isDigest(id) && record(v) &&
        same(Object.keys(v).sort(),['content','link','published','title','updated']) && Object.values(v).every(isDigest)) &&
        rows.every(x=>Object.hasOwn(entries,x.id) && ['new','edited'].includes(x.change) && Array.isArray(x.changedFields) && x.changedFields.length),
        'Malformed feed state or revision.');
  route=rows.length?'REVIEW_CHANGES':(!summary.entries?'EMPTY_FEED':summary.previousOnly?'FEED_WINDOW_CHANGED':'UNCHANGED');
  // A temporarily empty stream must never wipe the last good baseline.
  advanceBaseline=summary.entries>0;
  if(advanceBaseline) nextCapture=cp;
  result={changes:rows,entries:summary.entries,previousOnly:summary.previousOnly};
} else {
  const report=$('Read detail').first().json.body, overview=rows[0], mode=preview?'preview':'audit';
  const fields=c.flow==='supplier'?['matchedSkus','unionSkus','exceptionSkus','counts']:['mappedUrls','fullyTracedUrls','flaggedUrls','findingCounts','comparison'];
  check(rows.length===1 && record(report) && record(overview) && report.schemaVersion===1 &&
    report.kind===(c.flow==='supplier'?'catalog-reconciliation':'migration-redirect-audit') &&
    ['kind','schemaVersion','demoCase','outcome','outputMode',...fields].every(k=>k in report && k in overview && same(overview[k],report[k])) &&
    summary.outputMode===mode && report.outputMode===mode && summary.deliveredReports===1 &&
    summary.chargedEvents===expectedCharge && summary.eventName===(preview?null:event) &&
    digest(report)===summary.reportSha256 && summary.reportSha256===overview.reportSha256,'Report fingerprint, summary or mode mismatch.');
  if(c.flow==='supplier') {
    check(integer(report.exceptionSkus) && integer(report.unionSkus) && report.unionSkus>=report.exceptionSkus &&
      ['differences','clean'].includes(report.outcome) && (report.outcome==='clean')===(report.exceptionSkus===0) &&
      Array.isArray(report.exceptions) && report.exceptions.length===(preview?Math.min(3,report.exceptionSkus):report.exceptionSkus) &&
      new Set(report.exceptions.map(x=>x.sku)).size===report.exceptions.length &&
      report.exceptions.every(x=>typeof x.sku==='string' && Array.isArray(x.reasons) && x.reasons.length),'Supplier coverage mismatch.');
    if (!preview) check(report.incoming.sourceRows===c.input.incoming.rows.length && integer(report.incoming.uniqueSkus) &&
                        report.incoming.uniqueSkus>0 && isDigest(report.incoming.snapshotSha256),'Supplier input coverage mismatch.');
    route=preview?'DEMO_ONLY':report.exceptionSkus?'REVIEW_CATALOG_CHANGES':'CLEAN_CATALOG';
    advanceBaseline=!preview;
    if(advanceBaseline) nextCapture=c.input.incoming;
  } else {
    check(integer(report.mappedUrls) && report.mappedUrls>0 && report.fullyTracedUrls===report.mappedUrls &&
      integer(report.flaggedUrls) && report.flaggedUrls<=report.mappedUrls && ['clean','findings'].includes(report.outcome) &&
      (report.outcome==='clean')===(report.flaggedUrls===0) && Array.isArray(report.results) &&
      report.results.length===(preview?Math.min(3,report.mappedUrls):report.mappedUrls) &&
      new Set(report.results.map(x=>x.source)).size===report.results.length &&
      report.results.every(x=>x.source && x.expected && Array.isArray(x.findings)),'Missing or inconsistent migration traces.');
    if (!preview) check(report.results.every(x=>Array.isArray(x.hops)&&'finalStatus' in x && 'finalUrl' in x) &&
       report.results.filter(x=>x.findings.length).length===report.flaggedUrls,'Missing migration evidence.');
    route=preview?'DEMO_ONLY':report.flaggedUrls?'HOLD_RELEASE':'READY_FOR_SIGN_OFF';
  }
  result=report;
}
return [{json:{route,result,runId:run.id,storeId:run.defaultKeyValueStoreId,datasetId:run.defaultDatasetId,
 baselineStore:advanceBaseline?run.defaultKeyValueStoreId:state.state.baselineStore,
 baselineDigest:advanceBaseline?digest(nextCapture):state.state.baselineDigest??null,
 event,verifiedUnits:expectedCharge}}];

const c=$('Configure connection').first().json;
const {stateSha:sha,runId}=$('Prepare lookup').first().json;
const nextState={version:1,lastSequence:c.sequence,baselineStore:$json.baselineStore,
 baselineDigest:$json.baselineDigest,pending:null,lastRunId:runId,lastRoute:$json.route};

if(!/^[a-f0-9]{40}$/.test(sha??''))throw new Error('Journal revision missing.');
const content=Buffer.from(JSON.stringify(nextState),'utf8').toString('base64');
return [{json:{journalWrite:{message:'Update workflow journal',sha,content}}}];

const sha=$json.body?.content?.sha;
if(!/^[a-f0-9]{40}$/.test(sha??'') || sha===$('Prepare lookup').first().json.stateSha)throw new Error('Final journal update is unconfirmed. Inspect private state and the original run.');
const r=$('Verify delivery and charges').first().json;
return [{json:{...r,sequence:$('Configure connection').first().json.sequence}}];
